style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* === BACKGROUND GIF === */
  html, body {
    background: url("https://cdn.discordapp.com/attachments/1158087215398801489/1440185420364382248/rhdxh.gif") center/cover fixed !important;
    background-attachment: fixed !important;
    background-size: cover !important;
  }

  /* === MAKE UI TRANSPARENT & GRAY/BLACK PANELS === */
  body, .content,
  #container-main, .rbx-body, .rbx-content, .content, .theme-container, .container-main,
  div[style*="background-color"], section[style*="background-color"],
  [class*="container"], [class*="panel"], [class*="card"], [class*="content"] {
    background: transparent !important;
    color: #fff !important;
  }

  /* Panels & Cards */
  .section, .game-card, .profile-container, .recommendation-carousel,
  .friends-list, .avatar-card-container, .profile-header,
  .UniversalApp > div:not(.thumbnail) {
    background: rgba(30, 30, 30, 0.50) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 12px !important;
    color: #fff !important;
  }

  /* Sidebar */
  #navigation, .left-col, .nav-section {
    background: rgba(20, 20, 20, 0.60) !important;
    backdrop-filter: blur(10px) !important;
    border-radius: 10px !important;
    color: #fff !important;
  }

  /* Topbar */
  #navigation-container, .rbx-navbar {
    background: rgba(15, 15, 15, 0.70) !important;
    backdrop-filter: blur(10px) !important;
    color: #fff !important;
  }

  /* Navbar icons */
  .rbx-navbar svg, #navigation-container svg {
    filter: brightness(0) invert(1) !important;
  }

  /* Text / Links / General */
  body, span, p, a, div, .text, .rbx-text {
    color: #e5e5e5 !important;
  }

  /* Game thumbnails keep original + remove tints */
  .game-card-thumb-container img,
  .thumbnail-2d-container img {
    background: transparent !important;
    border-radius: 12px !important;
    filter: none !important;
  }

  /* Buttons */
  button, .btn-common {
    background: rgba(50, 50, 50, 0.45) !important;
    color: #fff !important;
    backdrop-filter: blur(4px) !important;
    border-radius: 10px !important;
  }
}
